  especificaciones, aplicaciones_es, aplicaciones_en,
  tipo_comercial, fulfillment_mode, precio, moneda, stock,
  disponible, destacado, nuevo, activo, orden, atributos
) VALUES (
  '74f21d04-d798-4fce-91e9-c40312f8b6f0'::uuid,
  'analizador-bioquimico-semiautomatico-rayto-rt-1904c',
  '4d9a59cd-2c1e-4755-9584-28d6e9024d3c'::uuid,
  NULL,
  'Analizador bioquímico semiautomático Rayto RT-1904C',
  'Rayto RT-1904C Semi-Automatic Biochemistry Analyzer',
  'Analizador bioquímico semiautomático Rayto RT-1904C con pantalla LCD 7", 160 protocolos, celda de flujo y modos cinético, fijo y punto final',
  'Rayto RT-1904C semi-automatic biochemistry analyzer with 7" LCD, 160 protocols, flow cell and kinetic, fixed-time and endpoint modes',
  'El Rayto RT-1904C es un analizador bioquímico semiautomático orientado a laboratorios clínicos que necesitan química clínica con operación sencilla sobre Windows, mouse y pantalla LCD a color de 7". Según el inserto del fabricante, trabaja con sistema de reactivo abierto (celda de flujo o cubeta a solicitud; el sistema puede cerrarse), modos cinético, fijo y punto final bicromático, con o sin blanco de reactivo o muestra, y calibración lineal y no lineal. Monitorea la curva de reacción en tiempo real, almacena hasta 160 protocolos y un mínimo de 500 resultados, incorpora control de calidad Westgard / Levey-Jennings (2 controles por prueba), auto encendido, auto-zero y autodiagnóstico, y facilita el mantenimiento de lámpara y tubuladuras sin depender de ingeniero para cambios básicos. Rango fotométrico −0,500 a 3,000 Abs; longitudes de onda 340, 405, 500, 546, 578, 620 y 670 nm más filtro opcional; celda de flujo de 25 µL; volumen de aspiración 100–3000 µL; control de temperatura 25/30/37 °C ±0,1 °C. Dimensiones publicadas 460 × 330 × 140 mm; peso neto 8 kg. La configuración final, reactivos, instalación y soporte se confirman en cotización.',
  'The Rayto RT-1904C is a semi-automatic biochemistry analyzer for clinical labs that need chemistry assays with simple Windows operation, mouse and a 7" color LCD. Per the manufacturer insert, it supports an open reagent system (flow cell or on-demand cuvette; the system can be closed), kinetic, fixed-time and bichromatic endpoint modes with or without reagent/sample blank, plus linear and non-linear calibration. It monitors the reaction curve in real time, stores up to 160 protocols and at least 500 results, includes Westgard / Levey-Jennings QC (2 controls per test), auto power-on, auto-zero and self-diagnosis, and simplifies lamp and tubing maintenance for routine changes. Photometric range −0.500 to 3.000 Abs; wavelengths 340, 405, 500, 546, 578, 620 and 670 nm plus optional filter; 25 µL flow cell; aspiration volume 100–3000 µL; temperature control 25/30/37 °C ±0.1 °C. Published size 460 × 330 × 140 mm; net weight 8 kg. Final configuration, reagents, installation and support are confirmed in the quotation.',
  '/assets/productos/bioquimica/rayto-rt-1904c/producto.jpg',
  ARRAY['/assets/productos/bioquimica/rayto-rt-1904c/producto.jpg', '/assets/productos/bioquimica/rayto-rt-1904c/hero-brochure.jpg', '/assets/productos/bioquimica/rayto-rt-1904c/ui-0.jpeg', '/assets/productos/bioquimica/rayto-rt-1904c/ui-2.jpeg'],
  '/assets/productos/bioquimica/rayto-rt-1904c/ficha-tecnica.pdf',
  '[{"clave": "Rango fotométrico","grupo": "Óptica","valor": "−0,500 a 3,000 Abs"},{"clave": "Resolución","grupo": "Óptica","valor": "0,001 Abs (muestra); 0,001 Abs (calculado)"},{"clave": "Fuente de luz","grupo": "Óptica","valor": "Lámpara halógena 6 V / 10 W"},{"clave": "Longitudes de onda","grupo": "Óptica","valor": "340, 405, 500, 546, 578, 620, 670 nm + filtro opcional; precisión ±1 nm; ancho de banda 8 nm"},{"clave": "Celda de flujo","grupo": "Muestreo","valor": "25 µL, metal y cuarzo; cubeta opcional 12,5 × 12,5 mm"},{"clave": "Volumen de aspiración","grupo": "Muestreo","valor": "100–3000 µL (bomba peristáltica); contaminación cruzada <0,1 %"},{"clave": "Métodos","grupo": "Análisis","valor": "Cinético, fijo, punto final bicromático; calibración lineal y no lineal"},{"clave": "Memoria","grupo": "Datos","valor": "Hasta 160 protocolos; mínimo 500 resultados"},{"clave": "Control de calidad","grupo": "Datos","valor": "Reglas Westgard; gráficos Levey-Jennings; 2 controles por prueba"},{"clave": "Temperatura","grupo": "Instalación","valor": "25 °C, 30 °C, 37 °C ±0,1 °C"},{"clave": "Pantalla e interfaz","grupo": "Interfaz","valor": "LCD 7\" color; RS-232; PSTN opcional; mouse/teclado externos opcionales; impresora interna o externa"},{"clave": "Dimensiones y peso","grupo": "Instalación","valor": "460 × 330 × 140 mm; peso neto 8 kg"},{"clave": "Alimentación","grupo": "Instalación","valor": "AC 110/220 V ±10 %, 50/60 Hz"}]'::jsonb,
  ARRAY['Química clínica semiautomática en laboratorio hospitalario o IPS', 'Protocolos programables de enzimas y sustratos con curva de reacción en tiempo real', 'Laboratorios que requieren QC Westgard/Levey-Jennings y reporte de paciente'],
  ARRAY['Semi-automatic clinical chemistry in hospital or outpatient labs', 'Programmable enzyme and substrate protocols with real-time reaction curves', 'Labs needing Westgard/Levey-Jennings QC and patient reporting'],
  'equipo',
  'cotizacion',
  NULL,
  'COP',
  0,
  TRUE, FALSE, TRUE, TRUE,
  468,
  '{"marca": "Rayto","fabricante": "Rayto Life and Analytical Sciences Co.,Ltd.","distribuidor": "I-ME","ref_proveedor": "RT-1904C","fuente_ficha": "175040003.DOC_INSERTO_SAP.175138.pdf (inserto Rayto RT-1904C)","nota_precio": "Sin precio público; fulfillment cotización. No publicar costos de suministro.","beneficios_es": ["Opera con interfaz Windows, mouse y LCD a color de 7\", lo que reduce la curva de aprendizaje frente a equipos solo por menús numéricos.","Cubre modos cinético, fijo y punto final bicromático con monitoreo de curva en tiempo real para reforzar la fiabilidad del resultado.","Guarda hasta 160 protocolos y al menos 500 resultados, con QC Westgard / Levey-Jennings (2 controles por prueba).","Celda de flujo de 25 µL y aspiración 100–3000 µL con contaminación cruzada <0,1 %, útil para paneles de bajo volumen.","Mantenimiento cotidiano de lámpara y tubuladuras sin depender de ingeniero para cambios básicos, según el inserto Rayto."],"beneficios_en": ["Runs with Windows UI, mouse and a 7\" color LCD, lowering the learning curve versus numeric-menu-only analyzers.","Covers kinetic, fixed-time and bichromatic endpoint modes with real-time curve monitoring to support result reliability.","Stores up to 160 protocols and at least 500 results, with Westgard / Levey-Jennings QC (2 controls per test).","25 µL flow cell and 100–3000 µL aspiration with <0.1 % carryover for lower-volume panels.","Routine lamp and tubing maintenance without calling an engineer for basic changes, per the Rayto insert."],"valor_es": "Bioquímica semiautomática compacta (460×330×140 mm, 8 kg) con 160 protocolos, QC documental y curva en tiempo real para laboratorios que cotizan equipo Rayto sin ampliar la bancada.","valor_en": "Compact semi-automatic chemistry (460×330×140 mm, 8 kg) with 160 protocols, documented QC and real-time curves for labs quoting Rayto without expanding the bench.","preguntas_frecuentes_es": [{"q": "¿Qué longitudes de onda trae el RT-1904C?","a": "El inserto Rayto lista 340, 405, 500, 546, 578, 620 y 670 nm, más un filtro opcional; precisión ±1 nm y ancho de banda 8 nm."},{"q": "¿Usa celda de flujo o cubeta?","a": "Soporta celda de flujo de 25 µL (metal y cuarzo) y modo de cubeta opcional 12,5×12,5 mm; el sistema de reactivo puede abrirse o cerrarse según configuración."},{"q": "¿Qué control de calidad incluye?","a": "Reglas Westgard y gráficos Levey-Jennings con 2 controles por prueba, según la ficha del fabricante."},{"q": "¿El PDF fija la configuración contractual?","a": "No necesariamente. Es inserto genérico Rayto (RT-1904C); reactivos, idiomas, instalación y accesorios se validan en la cotización I-ME."},{"q": "¿Se publica precio de lista en la web?","a": "No. El equipo se ofrece en modo cotización; el precio institucional se confirma al comprador."}],"preguntas_frecuentes_en": [{"q": "Which wavelengths does the RT-1904C include?","a": "The Rayto insert lists 340, 405, 500, 546, 578, 620 and 670 nm plus an optional filter; ±1 nm accuracy and 8 nm bandwidth."},{"q": "Flow cell or cuvette?","a": "It supports a 25 µL metal/quartz flow cell and an optional 12.5×12.5 mm cuvette mode; the reagent system can be open or closed depending on configuration."},{"q": "What QC is included?","a": "Westgard rules and Levey-Jennings charts with 2 controls per test, per the manufacturer sheet."},{"q": "Is the PDF contractual?","a": "Not necessarily. It is a generic Rayto insert (RT-1904C); reagents, languages, installation and accessories are validated in the I-ME quotation."},{"q": "Is a list price published online?","a": "No. The analyzer is offered in quotation mode; institutional pricing is confirmed to the buyer."}],"seo_keywords_es": ["analizador bioquímico Rayto RT-1904C","química clínica semiautomática Colombia","analizador bioquímica celda de flujo","Rayto RT-1904C cotización","laboratorio bioquímico semiautomático"],"seo_keywords_en": ["Rayto RT-1904C biochemistry analyzer","semi-automatic clinical chemistry Colombia","flow cell chemistry analyzer","Rayto RT-1904C quote","semi-auto biochemistry analyzer lab"],"imagen_principal": "/assets/productos/bioquimica/rayto-rt-1904c/producto.jpg","galeria": ["/assets/productos/bioquimica/rayto-rt-1904c/producto.jpg","/assets/productos/bioquimica/rayto-rt-1904c/hero-brochure.jpg","/assets/productos/bioquimica/rayto-rt-1904c/ui-0.jpeg","/assets/productos/bioquimica/rayto-rt-1904c/ui-2.jpeg"]}'::jsonb
)
