INSERT INTO public.productos (
  id, slug, familia_id, tipo_id,
  nombre_es, nombre_en,
  descripcion_corta_es, descripcion_corta_en,
  descripcion_larga_es, descripcion_larga_en,
  imagen_principal, galeria, ficha_pdf,
  especificaciones, aplicaciones_es, aplicaciones_en,
  tipo_comercial, fulfillment_mode, precio, moneda, stock,
  disponible, destacado, nuevo, activo, orden, atributos
) VALUES (
  '08b935d0-17e9-4589-b665-af56b3665cc8'::uuid,
  'analizador-bioquimico-semiautomatico-biobase-claire',
  '4d9a59cd-2c1e-4755-9584-28d6e9024d3c'::uuid,
  NULL,
  'Analizador bioquímico semiautomático BIOBASE-Claire',
  'BIOBASE-Claire Semi-auto Chemistry Analyzer',
  'Analizador bioquímico semiautomático BIOBASE-Claire: pantalla táctil 7", 144 ítems, 5.600 resultados, celda de flujo y 7 longitudes de onda',
  'BIOBASE-Claire semi-auto chemistry analyzer: 7" touchscreen, 144 items, 5,600 results, flow-through cuvette and 7 wavelengths',
  'El BIOBASE-Claire es un analizador de química clínica semiautomático de bancada documentado en la ficha conjunta BIOBASE Claire & Silver. Incorpora pantalla táctil LCD de 7,0" con interfaz gráfica, memoria para 144 ítems de prueba y 5.600 resultados, impresora térmica integrada con marcado de resultados anormales, y celda de flujo de lectura directa. Métodos: punto final, tiempo fijo (dos puntos) y dinámico (cinético). Longitudes de onda 340/405/450/510/546/578/630 nm con 2 posiciones abiertas para filtros adicionales y precisión ±2 nm. Idiomas: inglés, francés y español (otros bajo personalización). Interfaces RS-232 y USB; consumo 100 VA; alimentación AC 110/220 V ±10 %, 50/60 Hz; tamaño externo 400 × 410 × 190 mm; peso neto 8 kg / bruto 11 kg. Tipos de muestra indicados en ficha: suero, plasma, orina y líquido cefalorraquídeo. Configuración, reactivos, instalación y soporte se confirman en cotización.',
  'BIOBASE-Claire is a bench-top semi-automatic clinical chemistry analyzer documented in the joint BIOBASE Claire & Silver datasheet. It includes a 7.0" LCD touchscreen with graphical UI, memory for 144 test items and 5,600 results, a built-in thermal printer with abnormal-result flags, and a direct-reading flow-through cuvette. Methods: endpoint, fixed-time (two-point) and dynamic (rate). Wavelengths 340/405/450/510/546/578/630 nm with 2 open filter positions and ±2 nm accuracy. Languages: English, French and Spanish (others customizable). RS-232 and USB; consumption 100 VA; AC 110/220 V ±10 %, 50/60 Hz; external size 400 × 410 × 190 mm; net weight 8 kg / gross 11 kg. Sample types listed: serum, plasma, urine and cerebrospinal fluid. Configuration, reagents, installation and support are confirmed in the quotation.',
  '/assets/productos/bioquimica/biobase-claire/producto.jpg',
  ARRAY['/assets/productos/bioquimica/biobase-claire/producto.jpg', '/assets/productos/bioquimica/biobase-claire/hero-brochure.jpg'],
  '/assets/productos/bioquimica/biobase-claire/ficha-tecnica.pdf',
  '[{"clave": "Modelo","grupo": "Identificación","valor": "BIOBASE-Claire"},{"clave": "Tipos de muestra","grupo": "Muestreo","valor": "Suero, plasma, orina y líquido cefalorraquídeo (según ficha)"},{"clave": "Métodos","grupo": "Análisis","valor": "Punto final, tiempo fijo (dos puntos), dinámico (cinético)"},{"clave": "Cubeta","grupo": "Muestreo","valor": "Celda de flujo de lectura directa"},{"clave": "Longitudes de onda","grupo": "Óptica","valor": "340/405/450/510/546/578/630 nm + 2 posiciones abiertas; precisión ±2 nm"},{"clave": "Pantalla","grupo": "Interfaz","valor": "LCD táctil 7,0\""},{"clave": "Idiomas","grupo": "Interfaz","valor": "Inglés, francés, español; otros personalizables"},{"clave": "Impresora","grupo": "Interfaz","valor": "Térmica integrada; marca resultados anormales"},{"clave": "Memoria","grupo": "Datos","valor": "144 ítems de prueba; 5.600 resultados"},{"clave": "Interfaces","grupo": "Conectividad","valor": "RS-232, USB"},{"clave": "Consumo y alimentación","grupo": "Instalación","valor": "100 VA; AC 110/220 V ±10 %, 50/60 Hz"},{"clave": "Dimensiones y peso","grupo": "Instalación","valor": "400 × 410 × 190 mm; neto 8 kg; embalaje 520 × 490 × 330 mm; bruto 11 kg"}]'::jsonb,
  ARRAY['Química clínica semiautomática en laboratorios de volumen bajo-medio', 'Ensayos de suero, plasma, orina o LCR con celda de flujo', 'Flujos que necesitan impresora térmica y pantalla táctil 7" en bancada compacta'],
  ARRAY['Semi-automatic clinical chemistry in low-to-mid volume laboratories', 'Serum, plasma, urine or CSF assays via flow-through cuvette', 'Workflows needing a thermal printer and 7" touchscreen on a compact bench'],
  'equipo',
  'cotizacion',
  NULL,
  'COP',
  0,
  TRUE, FALSE, TRUE, TRUE,
  469,
  '{"marca": "BIOBASE","fabricante": "BIOBASE","distribuidor": "I-ME","ref_proveedor": "BIOBASE-Claire","fuente_ficha": "19-20 Semi-auto Chemistry Analyzer BIOBASE-Claire&BIOBASE-Silver(4).pdf","nota_precio": "Sin precio público; fulfillment cotización.","beneficios_es": ["Pantalla táctil de 7,0\" con interfaz gráfica facilita la operación diaria frente a menús solo por teclado.","Almacena 144 ítems y 5.600 resultados para laboratorios que rotan paneles sin depender de PC externo.","Impresora térmica integrada marca resultados anormales para revisión inmediata en mesa.","Siete longitudes de onda fijas más 2 filtros abiertos (±2 nm) cubren el espectro habitual de química clínica.","Huella 400×410×190 mm y 8 kg netos: cabe en bancadas pequeñas sin sacrificar USB/RS-232."],"beneficios_en": ["7.0\" touchscreen with graphical UI eases daily operation versus keyboard-only menus.","Stores 144 items and 5,600 results for labs that rotate panels without an external PC.","Built-in thermal printer flags abnormal results for immediate bench review.","Seven fixed wavelengths plus 2 open filters (±2 nm) cover common clinical chemistry spectra.","400×410×190 mm footprint and 8 kg net weight fit small benches while keeping USB/RS-232."],"valor_es": "Entrada BIOBASE a química semiautomática: 7\" táctil, 144 ítems y celda de flujo en 8 kg para laboratorios que cotizan Claire antes de subir a Silver.","valor_en": "BIOBASE entry to semi-auto chemistry: 7\" touch, 144 items and flow cell in 8 kg for labs quoting Claire before stepping up to Silver.","preguntas_frecuentes_es": [{"q": "¿Cuántos ítems y resultados guarda Claire?","a": "La ficha BIOBASE indica 144 ítems de prueba y 5.600 resultados."},{"q": "¿Qué métodos analíticos soporta?","a": "Punto final, tiempo fijo (dos puntos) y dinámico (método de tasa/cinético)."},{"q": "¿En qué se diferencia de BIOBASE-Silver?","a": "Según la misma ficha: Claire lista 144 ítems / 5.600 resultados y 100 VA; Silver lista 300 ítems / 20.000 resultados, 20 posiciones de incubación, 150 VA y 9 kg netos."},{"q": "¿La ficha es exclusiva de Claire?","a": "No. El PDF fuente es la hoja conjunta “Semi-auto Chemistry Analyzer BIOBASE-Claire & BIOBASE-Silver”; cada landing usa solo los parámetros de su columna."},{"q": "¿Hay precio publicado?","a": "No. Se cotiza; el precio institucional se confirma al comprador."}],"preguntas_frecuentes_en": [{"q": "How many items and results does Claire store?","a": "The BIOBASE sheet lists 144 test items and 5,600 results."},{"q": "Which analytical methods are supported?","a": "Endpoint, fixed-time (two-point) and dynamic (rate) methods."},{"q": "How does it differ from BIOBASE-Silver?","a": "Per the same sheet: Claire lists 144 items / 5,600 results and 100 VA; Silver lists 300 items / 20,000 results, 20 incubating positions, 150 VA and 9 kg net."},{"q": "Is the datasheet Claire-only?","a": "No. The source PDF is the joint “BIOBASE-Claire & BIOBASE-Silver” page; each landing uses only its column parameters."},{"q": "Is a price published?","a": "No. It is quoted; institutional pricing is confirmed to the buyer."}],"seo_keywords_es": ["BIOBASE-Claire analizador bioquímico","química clínica semiautomática BIOBASE","analizador bioquímica pantalla táctil 7","BIOBASE Claire cotización Colombia","celda de flujo laboratorio"],"seo_keywords_en": ["BIOBASE-Claire chemistry analyzer","BIOBASE semi-auto clinical chemistry","7 inch touchscreen biochemistry analyzer","BIOBASE Claire quote Colombia","flow-through cuvette analyzer"],"imagen_principal": "/assets/productos/bioquimica/biobase-claire/producto.jpg","galeria": ["/assets/productos/bioquimica/biobase-claire/producto.jpg","/assets/productos/bioquimica/biobase-claire/hero-brochure.jpg"]}'::jsonb
)
