INSERT INTO public.productos (
  id, slug, familia_id, tipo_id,
  nombre_es, nombre_en,
  descripcion_corta_es, descripcion_corta_en,
  descripcion_larga_es, descripcion_larga_en,
  imagen_principal, galeria, ficha_pdf,
  especificaciones, aplicaciones_es, aplicaciones_en,
  tipo_comercial, fulfillment_mode, precio, moneda, stock,
  disponible, destacado, nuevo, activo, orden, atributos
) VALUES (
  '18f5314a-b532-4b03-a847-b229bc94a779'::uuid,
  'analizador-bioquimico-semiautomatico-biobase-silver',
  '4d9a59cd-2c1e-4755-9584-28d6e9024d3c'::uuid,
  NULL,
  'Analizador bioquímico semiautomático BIOBASE-Silver',
  'BIOBASE-Silver Semi-auto Chemistry Analyzer',
  'Analizador bioquímico semiautomático BIOBASE-Silver: 300 ítems, 20.000 resultados, 20 posiciones de incubación y pantalla táctil 7"',
  'BIOBASE-Silver semi-auto chemistry analyzer: 300 items, 20,000 results, 20 incubating positions and 7" touchscreen',
  'El BIOBASE-Silver es la variante de mayor capacidad de la ficha conjunta Claire & Silver. Según parámetros del fabricante: pantalla táctil LCD 7,0", memoria para 300 ítems y 20.000 resultados, impresora térmica con flag de anormales, 20 posiciones de incubación y control de temperatura ambiente / 25 / 30 / 37 °C. Métodos punto final, tiempo fijo y dinámico; celda de flujo de lectura directa; longitudes de onda 340/405/450/510/546/578/630 nm + 2 filtros abiertos (±2 nm). Idiomas EN/FR/ES; RS-232 y USB; consumo 150 VA; AC 110/220 V ±10 %, 50/60 Hz; tamaño 400 × 410 × 190 mm; peso neto 9 kg / bruto 12 kg. Tipos de muestra: suero, plasma, orina y LCR. Configuración final en cotización.',
  'BIOBASE-Silver is the higher-capacity variant on the joint Claire & Silver datasheet. Manufacturer parameters: 7.0" LCD touchscreen, memory for 300 items and 20,000 results, thermal printer with abnormal flags, 20 incubating positions and room-temperature / 25 / 30 / 37 °C control. Endpoint, fixed-time and dynamic methods; direct-reading flow-through cuvette; wavelengths 340/405/450/510/546/578/630 nm + 2 open filters (±2 nm). Languages EN/FR/ES; RS-232 and USB; 150 VA; AC 110/220 V ±10 %, 50/60 Hz; size 400 × 410 × 190 mm; net 9 kg / gross 12 kg. Sample types: serum, plasma, urine and CSF. Final configuration in quotation.',
  '/assets/productos/bioquimica/biobase-silver/producto.jpg',
  ARRAY['/assets/productos/bioquimica/biobase-silver/producto.jpg', '/assets/productos/bioquimica/biobase-silver/hero-brochure.jpg'],
  '/assets/productos/bioquimica/biobase-silver/ficha-tecnica.pdf',
