  '{"marca": "BIOBASE","fabricante": "BIOBASE","distribuidor": "I-ME","ref_proveedor": "BIOBASE-Silver","fuente_ficha": "19-20 Semi-auto Chemistry Analyzer BIOBASE-Claire&BIOBASE-Silver(4).pdf","nota_precio": "Sin precio público; fulfillment cotización.","beneficios_es": ["Sube la memoria a 300 ítems y 20.000 resultados frente a Claire (144 / 5.600) sin cambiar la huella 400×410×190 mm.","Aporta 20 posiciones de incubación con T. ambiente / 25 / 30 / 37 °C para protocolos que requieren preincubación en bancada.","Mantiene pantalla táctil 7\", impresora térmica con flags y misma batería óptica de 7+2 longitudes de onda.","Consumo 150 VA con USB/RS-232 para conectar a flujos de laboratorio existentes.","Misma familia visual BIOBASE que Claire, útil cuando la institución quiere estandarizar marca y subir capacidad."],"beneficios_en": ["Raises memory to 300 items and 20,000 results versus Claire (144 / 5,600) without changing the 400×410×190 mm footprint.","Adds 20 incubating positions with ambient / 25 / 30 / 37 °C for protocols that need bench pre-incubation.","Keeps the 7\" touchscreen, thermal printer with flags and the same 7+2 wavelength optical set.","150 VA draw with USB/RS-232 to connect into existing lab workflows.","Same BIOBASE visual family as Claire when institutions want brand standardization and more capacity."],"valor_es": "Claire+capacidad: mismos 7\" y óptica, con 20 incubaciones, 300 ítems y 20.000 resultados para laboratorios que ya cotizan Silver.","valor_en": "Claire+capacity: same 7\" and optics, with 20 incubations, 300 items and 20,000 results for labs already quoting Silver.","preguntas_frecuentes_es": [{"q": "¿Cuántas posiciones de incubación tiene?","a": "La ficha lista 20 posiciones de incubación con temperatura ambiente, 25 °C, 30 °C y 37 °C."},{"q": "¿Cuánta memoria tiene frente a Claire?","a": "Silver: 300 ítems y 20.000 resultados. Claire: 144 ítems y 5.600 resultados (misma ficha BIOBASE)."},{"q": "¿Comparte PDF con Claire?","a": "Sí. El archivo fuente es la hoja conjunta Claire & Silver; esta landing usa solo la columna Silver."},{"q": "¿Qué consumo eléctrico declara?","a": "150 VA a AC 110/220 V ±10 %, 50/60 Hz."},{"q": "¿Precio web?","a": "No. Modo cotización; precio institucional al comprador."}],"preguntas_frecuentes_en": [{"q": "How many incubating positions?","a": "The sheet lists 20 incubating positions with ambient, 25 °C, 30 °C and 37 °C."},{"q": "How does memory compare to Claire?","a": "Silver: 300 items and 20,000 results. Claire: 144 items and 5,600 results (same BIOBASE sheet)."},{"q": "Does it share a PDF with Claire?","a": "Yes. The source file is the joint Claire & Silver page; this landing uses only the Silver column."},{"q": "What power consumption is listed?","a": "150 VA at AC 110/220 V ±10 %, 50/60 Hz."},{"q": "Web price?","a": "None. Quotation mode; institutional price to the buyer."}],"seo_keywords_es": ["BIOBASE-Silver analizador bioquímico","analizador bioquímica 20 incubaciones","química semiautomática 300 ítems","BIOBASE Silver cotización","analizador clínico pantalla 7 pulgadas"],"seo_keywords_en": ["BIOBASE-Silver chemistry analyzer","20 incubating positions chemistry analyzer","semi-auto chemistry 300 test items","BIOBASE Silver quote","7 inch touchscreen clinical analyzer"],"imagen_principal": "/assets/productos/bioquimica/biobase-silver/producto.jpg","galeria": ["/assets/productos/bioquimica/biobase-silver/producto.jpg","/assets/productos/bioquimica/biobase-silver/hero-brochure.jpg"]}'::jsonb
)
