  especificaciones, aplicaciones_es, aplicaciones_en,
  tipo_comercial, fulfillment_mode, precio, moneda, stock,
  disponible, destacado, nuevo, activo, orden, atributos
) VALUES (
  'e3c6b8a1-34f9-4e9b-96e2-937ad3ce3386'::uuid,
  'analizador-bioquimico-semiautomatico-biobase-silver-plus',
  '4d9a59cd-2c1e-4755-9584-28d6e9024d3c'::uuid,
  NULL,
  'Analizador bioquímico semiautomático BIOBASE-Silver Plus',
  'BIOBASE-Silver Plus Semi-auto Chemistry Analyzer',
  'Analizador bioquímico semiautomático BIOBASE-Silver Plus: 20 incubaciones, 200 programas, 1.000 resultados y QC con gráfica',
  'BIOBASE-Silver Plus semi-auto chemistry analyzer: 20 incubations, 200 programs, 1,000 results and chartable QC',
  'El BIOBASE-Silver Plus aparece en ficha de producto como analizador de química semiautomático con operación simplificada (un botón) y conexión a computador. La documentación lista métodos de punto final, dos puntos (tiempo fijo), cinético, multiestándar y bicromático; 20 posiciones de incubación; memoria para 200 programas de prueba y 1.000 resultados; función de control de calidad con gráfica almacenable, visualizable e imprimible; tres niveles de temperatura (25 °C, 30 °C, 37 °C) seleccionables en celda de flujo e incubación; y gráfica en tiempo real visualizable e imprimible. La ficha de origen no publica tabla completa de longitudes de onda ni dimensiones; esos datos se confirman en cotización. Configuración, reactivos, instalación y soporte institucionales se validan al cotizar.',
  'BIOBASE-Silver Plus is presented on the product sheet as a semi-automatic chemistry analyzer with one-button operation and computer connection. Documentation lists endpoint, two-point (fixed-time), kinetic, multi-standard and bichromatic methods; 20 incubating positions; memory for 200 test programs and 1,000 results; QC with charts that can be stored, displayed and printed; three temperature levels (25 °C, 30 °C, 37 °C) selectable in the flow cell and incubator; and real-time graphs that can be displayed and printed. The source sheet does not publish a full wavelength or dimension table; those details are confirmed in quotation. Institutional configuration, reagents, installation and support are validated when quoting.',
  '/assets/productos/bioquimica/biobase-silver-plus/producto.jpg',
  ARRAY['/assets/productos/bioquimica/biobase-silver-plus/producto.jpg', '/assets/productos/bioquimica/biobase-silver-plus/hero-brochure.jpg'],
  '/assets/productos/bioquimica/biobase-silver-plus/ficha-tecnica.pdf',
  '[{"clave": "Modelo","grupo": "Identificación","valor": "BIOBASE-Silver Plus"},{"clave": "Operación","grupo": "Interfaz","valor": "Operación simplificada por un botón; conexión a computador"},{"clave": "Métodos","grupo": "Análisis","valor": "Punto final, dos puntos (tiempo fijo), cinético, multiestándar, bicromático, entre otros"},{"clave": "Incubación","grupo": "Temperatura","valor": "20 posiciones de incubación"},{"clave": "Temperatura","grupo": "Temperatura","valor": "25 °C, 30 °C, 37 °C seleccionables en celda de flujo e incubación"},{"clave": "Memoria","grupo": "Datos","valor": "200 programas de prueba; 1.000 resultados"},{"clave": "Control de calidad","grupo": "Datos","valor": "Gráfica QC almacenable, visualizable e imprimible"},{"clave": "Visualización","grupo": "Datos","valor": "Gráfica en tiempo real visualizable e imprimible"}]'::jsonb,
  ARRAY['Química clínica semiautomática con incubación de 20 posiciones', 'Laboratorios que requieren QC documental con gráfica imprimible', 'Flujos con conexión a computador y operación simplificada'],
  ARRAY['Semi-automatic clinical chemistry with 20-position incubation', 'Labs needing documented QC with printable charts', 'Workflows with computer connection and simplified operation'],
  'equipo',
  'cotizacion',
  NULL,
  'COP',
  0,
  TRUE, FALSE, TRUE, TRUE,
  471,
  '{"marca": "BIOBASE","fabricante": "BIOBASE","distribuidor": "I-ME","ref_proveedor": "BIOBASE-Silver Plus","fuente_ficha": "BIOBASE_Silver_Plus_Ficha_Producto.pdf (hoja features; branding KGC en documento fuente)","nota_precio": "Sin precio público; fulfillment cotización. Specs limitadas a features publicadas en ficha.","beneficios_es": ["Opera con un botón y puede conectarse a computador, reduciendo fricción en puestos de bajo volumen.","Incluye 20 posiciones de incubación y temperatura 25/30/37 °C en celda de flujo e incubación.","Guarda 200 programas y 1.000 resultados con QC y gráficas en tiempo real imprimibles.","Cubre punto final, tiempo fijo, cinético, multiestándar y bicromático según la ficha Silver Plus.","Complementa la línea Silver cuando la institución pide la variante Plus documentada por fabricante/distribuidor."],"beneficios_en": ["One-button operation with computer connection reduces friction in low-volume benches.","Includes 20 incubating positions and 25/30/37 °C control in flow cell and incubator.","Stores 200 programs and 1,000 results with printable QC and real-time graphs.","Covers endpoint, fixed-time, kinetic, multi-standard and bichromatic methods per the Silver Plus sheet.","Extends the Silver line when institutions request the Plus variant documented by manufacturer/distributor."],"valor_es": "Variante Plus de la línea Silver: 20 incubaciones, QC con gráfica y operación a un botón para laboratorios que cotizan Silver Plus con ficha de producto.","valor_en": "Plus variant of the Silver line: 20 incubations, chartable QC and one-button operation for labs quoting Silver Plus from the product sheet.","preguntas_frecuentes_es": [{"q": "¿Qué memoria declara Silver Plus?","a": "La ficha indica 200 programas de prueba y 1.000 resultados."},{"q": "¿Tiene incubación?","a": "Sí. Lista 20 posiciones de incubación y temperaturas 25/30/37 °C en celda de flujo e incubación."},{"q": "¿Por qué hay menos specs que en Silver?","a": "La ficha Silver Plus de origen solo publica el bloque de características; no incluye la tabla completa de longitudes de onda/dimensiones de la hoja Claire&Silver. Lo faltante se confirma en cotización."},{"q": "¿La marca KGC del PDF es el fabricante?","a": "La hoja muestra branding KGC sobre el producto BIOBASE-Silver Plus. El modelo publicado es BIOBASE; el canal comercial se confirma al cotizar."},{"q": "¿Precio en web?","a": "No. Cotización institucional."}],"preguntas_frecuentes_en": [{"q": "What memory does Silver Plus list?","a": "The sheet lists 200 test programs and 1,000 results."},{"q": "Does it include incubation?","a": "Yes. It lists 20 incubating positions and 25/30/37 °C in the flow cell and incubator."},{"q": "Why fewer specs than Silver?","a": "The source Silver Plus sheet only publishes the features block; it lacks the full wavelength/dimension table from the Claire&Silver page. Missing items are confirmed in quotation."},{"q": "Is KGC on the PDF the manufacturer?","a": "The sheet shows KGC branding over the BIOBASE-Silver Plus product. The published model is BIOBASE; the commercial channel is confirmed when quoting."},{"q": "Web price?","a": "No. Institutional quotation."}],"seo_keywords_es": ["BIOBASE-Silver Plus analizador","química semiautomática 20 incubaciones","analizador bioquímico QC gráfica","BIOBASE Silver Plus cotización","analizador bioquímica un botón"],"seo_keywords_en": ["BIOBASE-Silver Plus analyzer","semi-auto chemistry 20 incubations","chemistry analyzer QC chart","BIOBASE Silver Plus quote","one-button biochemistry analyzer"],"imagen_principal": "/assets/productos/bioquimica/biobase-silver-plus/producto.jpg","galeria": ["/assets/productos/bioquimica/biobase-silver-plus/producto.jpg","/assets/productos/bioquimica/biobase-silver-plus/hero-brochure.jpg"]}'::jsonb
)
