  especificaciones, aplicaciones_es, aplicaciones_en,
  tipo_comercial, fulfillment_mode, precio, moneda, stock,
  disponible, destacado, nuevo, activo, orden, atributos
) VALUES (
  'd2ff9c7c-ad3a-4d9b-bf40-6507370e5072'::uuid,
  'analizador-bioquimico-semiautomatico-sunnymed-sy-b010',
  '4d9a59cd-2c1e-4755-9584-28d6e9024d3c'::uuid,
  NULL,
  'Analizador bioquímico semiautomático SUNNYMED SY-B010',
  'SUNNYMED SY-B010 Semi-Auto Chemistry Analyzer',
  'Analizador bioquímico semiautomático SUNNYMED SY-B010: celda de cuarzo desde 32 µL, métodos cinético/punto final y alimentación 85–264 V',
  'SUNNYMED SY-B010 semi-auto chemistry analyzer: quartz cell from 32 µL, kinetic/endpoint methods and 85–264 V supply',
  'El SUNNYMED SY-B010 es un analizador de bioquímica / química clínica semiautomático de Sunny Medical Equipment Limited. La ficha técnica compilada a partir de información comercial publicada lista celda de flujo de cuarzo permanente con volumen mínimo indicado de 32 µL (opción de celda desechable), muestreo por sistema automático de presión para controlar la aspiración, y métodos de punto final, tiempo fijo, cinético, factor, multiestándar, bicromático y doble longitud de onda. Incorpora pantalla LCD de alto brillo, impresora térmica interna con posibilidad de impresora externa, volumen de muestra 10–50 µL, condiciones de trabajo 10–30 °C y humedad relativa 20–80 %, alimentación AC 85–264 V con adaptación automática, consumo ≤100 W y precisión de longitud de onda ±2 nm. Compatibilidad de software indicada: Windows Vista, XP y 2000. La fuente declara certificación CE en el listado comercial; no es un PDF original emitido por el fabricante. Configuración contractual, reactivos e instalación se confirman en cotización I-ME.',
  'The SUNNYMED SY-B010 is a semi-automatic biochemistry / clinical chemistry analyzer from Sunny Medical Equipment Limited. The datasheet compiled from published commercial information lists a permanent quartz flow cell with a stated minimum volume of 32 µL (disposable cell option), automatic pressure sampling to control aspiration, and endpoint, fixed-time, kinetic, factor, multi-standard, bichromatic and dual-wavelength methods. It includes a high-brightness LCD, internal thermal printer with external printer option, sample volume 10–50 µL, operating conditions 10–30 °C and 20–80 % RH, AC 85–264 V auto-ranging supply, ≤100 W consumption and ±2 nm wavelength accuracy. Listed software compatibility: Windows Vista, XP and 2000. The source states CE on the commercial listing; it is not an original manufacturer-issued PDF. Contractual configuration, reagents and installation are confirmed in the I-ME quotation.',
  '/assets/productos/bioquimica/sunnymed-sy-b010/producto.jpg',
  ARRAY['/assets/productos/bioquimica/sunnymed-sy-b010/producto.jpg', '/assets/productos/bioquimica/sunnymed-sy-b010/hero-brochure.jpg'],
  '/assets/productos/bioquimica/sunnymed-sy-b010/ficha-tecnica.pdf',
  '[{"clave": "Marca / modelo","grupo": "Identificación","valor": "SUNNYMED SY-B010"},{"clave": "Tipo","grupo": "Identificación","valor": "Analizador de bioquímica / química clínica semiautomático"},{"clave": "Celda de flujo","grupo": "Muestreo","valor": "Cuarzo permanente; volumen mínimo indicado 32 µL; opción celda desechable"},{"clave": "Muestreo","grupo": "Muestreo","valor": "Sistema automático de presión para controlar volumen de aspiración"},{"clave": "Volumen de muestra","grupo": "Muestreo","valor": "10–50 µL"},{"clave": "Métodos","grupo": "Análisis","valor": "Punto final, tiempo fijo, cinético, factor, multiestándar, bicromático y doble longitud de onda"},{"clave": "Precisión de longitud de onda","grupo": "Óptica","valor": "±2 nm (especificación publicada)"},{"clave": "Pantalla","grupo": "Interfaz","valor": "LCD de alto brillo"},{"clave": "Impresión","grupo": "Interfaz","valor": "Impresora térmica interna; posibilidad de impresora externa"},{"clave": "Condiciones de trabajo","grupo": "Instalación","valor": "10–30 °C; humedad relativa 20–80 %"},{"clave": "Alimentación y consumo","grupo": "Instalación","valor": "AC 85–264 V (adaptación automática); ≤100 W"},{"clave": "Compatibilidad indicada","grupo": "Software","valor": "Windows Vista, XP y 2000 (según ficha comercial)"},{"clave": "Certificación indicada","grupo": "Documentación","valor": "CE según listado comercial de origen; validar documentación regulatoria en cotización"}]'::jsonb,
  ARRAY['Química clínica semiautomática en laboratorios de bajo-medio volumen', 'Ensayos con microvolumen (10–50 µL) y celda de cuarzo desde 32 µL', 'Puestos que requieren impresora térmica y alimentación auto-rango 85–264 V'],
  ARRAY['Semi-automatic clinical chemistry in low-to-mid volume labs', 'Assays with micro-volume (10–50 µL) and quartz cell from 32 µL', 'Benches needing a thermal printer and 85–264 V auto-ranging supply'],
  'equipo',
  'cotizacion',
  NULL,
  'COP',
  0,
  TRUE, FALSE, TRUE, TRUE,
  472,
  '{"marca": "SUNNYMED","fabricante": "Sunny Medical Equipment Limited","distribuidor": "I-ME","ref_proveedor": "SY-B010","fuente_ficha": "SUNNYMED_SY-B010_Ficha_Tecnica.pdf (compilada desde listado comercial Made-in-China; no PDF OEM original)","fuente_url": "https://es.made-in-china.com/co_sunnymedgz/product_Clinical-Analytical-Device-Lab-Semi-Auto-Chemistry-Analyser-for-Sale_oyyririrg.html","nota_precio": "Sin precio público; fulfillment cotización. Validar documentación regulatoria en cotización.","beneficios_es": ["Celda de cuarzo permanente desde 32 µL (con opción desechable) orientada a paneles de bajo volumen.","Volumen de muestra 10–50 µL con aspiración controlada por presión automática.","Cubre punto final, tiempo fijo, cinético, factor, multiestándar, bicromático y doble longitud de onda.","Alimentación AC 85–264 V auto-rango y ≤100 W simplifica instalación en sedes con voltaje variable.","Impresora térmica interna (y externa opcional) para reporte en mesa sin PC dedicado."],"beneficios_en": ["Permanent quartz cell from 32 µL (disposable option) aimed at lower-volume panels.","Sample volume 10–50 µL with automatic pressure-controlled aspiration.","Covers endpoint, fixed-time, kinetic, factor, multi-standard, bichromatic and dual-wavelength methods.","AC 85–264 V auto-ranging supply and ≤100 W simplify installs on mixed-voltage sites.","Internal thermal printer (external optional) for bench reporting without a dedicated PC."],"valor_es": "Bioquímica semiautomática SUNNYMED con microvolumen y fuente 85–264 V para laboratorios que cotizan SY-B010 a partir de ficha comercial verificada.","valor_en": "SUNNYMED semi-auto chemistry with micro-volume and 85–264 V supply for labs quoting SY-B010 from verified commercial datasheet data.","preguntas_frecuentes_es": [{"q": "¿De dónde salen las especificaciones?","a": "De ficha maquetada con información comercial publicada por Sunny Medical Equipment Limited (Made-in-China). El propio PDF aclara que no es un PDF original del fabricante."},{"q": "¿Qué volumen de muestra usa?","a": "10–50 µL; la celda de cuarzo permanente indica volumen mínimo de 32 µL."},{"q": "¿Qué dice sobre certificación CE?","a": "El listado comercial de origen indica CE. La documentación regulatoria aplicable en Colombia se valida en la cotización; no se asume registro INVIMA desde esa mención."},{"q": "¿Qué sistemas operativos menciona?","a": "Vista, Windows XP y Windows 2000 según la ficha comercial; conviene confirmar compatibilidad real al cotizar."},{"q": "¿Hay precio en la web?","a": "No. Modo cotización."}],"preguntas_frecuentes_en": [{"q": "Where do the specs come from?","a": "From a datasheet compiled from commercial information published by Sunny Medical Equipment Limited (Made-in-China). The PDF itself states it is not an original manufacturer-issued PDF."},{"q": "What sample volume is used?","a": "10–50 µL; the permanent quartz cell states a 32 µL minimum volume."},{"q": "What about CE certification?","a": "The source commercial listing indicates CE. Applicable Colombian regulatory documentation is validated in quotation; INVIMA registration is not assumed from that mention."},{"q": "Which operating systems are listed?","a": "Vista, Windows XP and Windows 2000 per the commercial sheet; confirm real compatibility when quoting."},{"q": "Is there a web price?","a": "No. Quotation mode."}],"seo_keywords_es": ["SUNNYMED SY-B010","analizador bioquímico semiautomático SUNNYMED","química clínica celda cuarzo 32 µL","SY-B010 cotización Colombia","analizador bioquímica 85-264 V"],"seo_keywords_en": ["SUNNYMED SY-B010","SUNNYMED semi-auto chemistry analyzer","quartz flow cell 32 µL analyzer","SY-B010 quote Colombia","85-264 V biochemistry analyzer"],"imagen_principal": "/assets/productos/bioquimica/sunnymed-sy-b010/producto.jpg","galeria": ["/assets/productos/bioquimica/sunnymed-sy-b010/producto.jpg","/assets/productos/bioquimica/sunnymed-sy-b010/hero-brochure.jpg"]}'::jsonb
)
